#!/usr/bin/env python3
"""Offline WAN telemetry incident analyzer.

Reads JSON Lines requests on stdin, writes one JSON object per line on stdout.
Exact inference over the set of minimum-fault explanations.
"""

import sys
import json
import re
from math import lcm

NAME_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}\Z')
METRICS = frozenset(('demand', 'link', 'ingress', 'egress'))


class Invalid(Exception):
    """Schema violation."""


# --------------------------------------------------------------------------
# validation
# --------------------------------------------------------------------------

def _name(v):
    if type(v) is not str or NAME_RE.match(v) is None:
        raise Invalid()
    return v


def _int(v, lo, hi):
    if type(v) is not int or v < lo or v > hi:
        raise Invalid()
    return v


def _lst(v):
    if type(v) is not list:
        raise Invalid()
    return v


def _obj(v):
    if type(v) is not dict:
        raise Invalid()
    return v


def _parse_request(req):
    """Return the normalized instance; raise Invalid on any schema violation."""
    _obj(req)
    _int(req.get('version'), 1, 1)

    nodes = _lst(req.get('nodes'))
    if not 2 <= len(nodes) <= 12:
        raise Invalid()
    node_set = set()
    for n in nodes:
        _name(n)
        if n in node_set:
            raise Invalid()
        node_set.add(n)

    edges = _lst(req.get('edges'))
    if not 0 <= len(edges) <= 32:
        raise Invalid()
    edge_ids = set()
    edge_list = []
    for e in edges:
        _obj(e)
        eid = _name(e.get('id'))
        if eid in edge_ids:
            raise Invalid()
        edge_ids.add(eid)
        src = _name(e.get('source'))
        tgt = _name(e.get('target'))
        if src not in node_set or tgt not in node_set or src == tgt:
            raise Invalid()
        cap = _int(e.get('capacity'), 0, 1000000)
        edge_list.append((eid, src, tgt, cap))

    commodities = _lst(req.get('commodities'))
    if not 0 <= len(commodities) <= 12:
        raise Invalid()
    edge_index = {}
    for i, (eid, _s, _t, _c) in enumerate(edge_list):
        edge_index[eid] = i
    com_ids = set()
    pair_set = set()
    com_list = []
    for c in commodities:
        _obj(c)
        cid = _name(c.get('id'))
        if cid in com_ids:
            raise Invalid()
        com_ids.add(cid)
        src = _name(c.get('source'))
        tgt = _name(c.get('target'))
        if src not in node_set or tgt not in node_set or src == tgt:
            raise Invalid()
        if (src, tgt) in pair_set:
            raise Invalid()
        pair_set.add((src, tgt))
        routes = _lst(c.get('routes'))
        if not 1 <= len(routes) <= 3:
            raise Invalid()
        rlist = []
        wsum = 0
        for r in routes:
            _obj(r)
            eids = _lst(r.get('edges'))
            if len(eids) < 1:
                raise Invalid()
            w = _int(r.get('weight'), 1, 8)
            wsum += w
            if wsum > 8:
                raise Invalid()
            path = []
            cur = src
            seen = {src}
            for eid in eids:
                if type(eid) is not str or eid not in edge_index:
                    raise Invalid()
                _, es, et, _cap = edge_list[edge_index[eid]]
                if es != cur:
                    raise Invalid()
                cur = et
                if cur in seen:
                    raise Invalid()
                seen.add(cur)
                path.append(edge_index[eid])
            if cur != tgt:
                raise Invalid()
            rlist.append((path, w))
        com_list.append((cid, src, tgt, rlist))

    domains = _lst(req.get('domains'))
    if not 0 <= len(domains) <= 14:
        raise Invalid()
    dom_set = set()
    for d in domains:
        _name(d)
        if d in dom_set:
            raise Invalid()
        dom_set.add(d)
    max_faults = _int(req.get('max_faults'), 0, len(domains))

    snapshots = _lst(req.get('snapshots'))
    if not 1 <= len(snapshots) <= 4:
        raise Invalid()
    snap_ids = set()
    snap_list = []
    for sn in snapshots:
        _obj(sn)
        sid = _name(sn.get('id'))
        if sid in snap_ids:
            raise Invalid()
        snap_ids.add(sid)
        bounds = _lst(sn.get('bounds'))
        if len(bounds) != len(com_list):
            raise Invalid()
        bl = []
        for p in bounds:
            if type(p) is not list or len(p) != 2:
                raise Invalid()
            lo = _int(p[0], 0, 10000)
            hi = _int(p[1], 0, 10000)
            if lo > hi:
                raise Invalid()
            bl.append((lo, hi))
        ctrl = _lst(sn.get('controller'))
        if len(ctrl) != len(com_list):
            raise Invalid()
        ctrl = [_int(v, 0, 10000) for v in ctrl]
        tol = _int(sn.get('tolerance'), 0, 10000)
        obs = _lst(sn.get('observations'))
        if not 0 <= len(obs) <= 96:
            raise Invalid()
        olist = []
        oid_set = set()
        for o in obs:
            _obj(o)
            oid = _name(o.get('id'))
            if oid in oid_set:
                raise Invalid()
            oid_set.add(oid)
            metric = o.get('metric')
            if type(metric) is not str or metric not in METRICS:
                raise Invalid()
            target = _name(o.get('target'))
            if metric == 'demand':
                if target not in com_ids:
                    raise Invalid()
            elif metric == 'link':
                if target not in edge_ids:
                    raise Invalid()
            else:
                if target not in node_set:
                    raise Invalid()
            lo = _int(o.get('lower'), -1000000, 1000000)
            hi = _int(o.get('upper'), -1000000, 1000000)
            if lo > hi:
                raise Invalid()
            dom = o.get('domain')
            if dom is not None:
                if type(dom) is not str or dom not in dom_set:
                    raise Invalid()
            olist.append((oid, metric, target, lo, hi, dom))
        snap_list.append((sid, bl, ctrl, tol, olist))

    return {
        'nodes': sorted(node_set),
        'edges': edge_list,
        'commodities': com_list,
        'domains': domains,
        'max_faults': max_faults,
        'snapshots': snap_list,
    }


def _bad_constant(tok):
    raise Invalid()


def handle_line(raw):
    """Process one raw input line (bytes) and return the response object."""
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    try:
        req = json.loads(text, parse_constant=_bad_constant)
    except Exception:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    rid = None
    if type(req) is dict:
        v = req.get('id')
        if type(v) is str and NAME_RE.match(v) is not None:
            rid = v
    try:
        inst = _parse_request(req)
    except Invalid:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    except Exception:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    try:
        return analyze(inst, rid)
    except Exception:
        import traceback
        traceback.print_exc(file=sys.stderr)
        return {'id': rid, 'status': 'error', 'error': 'internal_error'}


# --------------------------------------------------------------------------
# exact inference
# --------------------------------------------------------------------------

def _fmt(fr):
    return '%d/%d' % (fr.numerator, fr.denominator)


def analyze(inst, rid):
    import z3

    edges = inst['edges']
    coms = inst['commodities']
    snaps = inst['snapshots']
    domains = inst['domains']
    max_faults = inst['max_faults']
    S = len(snaps)
    C = len(coms)
    E = len(edges)

    W = []
    coef = []
    for _cid, _src, _tgt, routes in coms:
        row = [0] * E
        wsum = 0
        for path, w in routes:
            wsum += w
            for ei in path:
                row[ei] += w
        W.append(wsum)
        coef.append(row)
    L = 1
    for w in W:
        L = lcm(L, w)
    A = [[coef[c][e] * (L // W[c]) for e in range(E)] for c in range(C)]

    q = [[z3.Int('q_%d_%d' % (s, c)) for c in range(C)] for s in range(S)]
    n = [[z3.Int('n_%d_%d' % (s, e)) for e in range(E)] for s in range(S)]

    base = []
    add = base.append
    for s in range(S):
        bnd = snaps[s][1]
        for c in range(C):
            lo, hi = bnd[c]
            add(q[s][c] >= lo)
            add(q[s][c] <= hi)
        for e in range(E):
            terms = [q[s][c] * A[c][e] for c in range(C) if A[c][e]]
            if terms:
                add(n[s][e] == z3.Sum(terms))
            else:
                add(n[s][e] == 0)
            add(n[s][e] <= L * edges[e][3])

    ing = {}
    egr = {}
    for i, (_cid, src, tgt, _r) in enumerate(coms):
        ing.setdefault(src, []).append(i)
        egr.setdefault(tgt, []).append(i)

    def obs_expr(s, metric, target):
        if metric == 'demand':
            for i, cinfo in enumerate(coms):
                if cinfo[0] == target:
                    return q[s][i]
        elif metric == 'link':
            for i, einfo in enumerate(edges):
                if einfo[0] == target:
                    return n[s][i]
        else:
            lst = ing.get(target, ()) if metric == 'ingress' else egr.get(target, ())
            terms = [q[s][i] for i in lst]
            if terms:
                return z3.Sum(terms)
            return z3.IntVal(0)
        raise AssertionError

    viol = {}
    for s, snap in enumerate(snaps):
        for (_oid, metric, target, lo, hi, dom) in snap[4]:
            expr = obs_expr(s, metric, target)
            sc = L if metric == 'link' else 1
            if dom is None:
                add(expr >= lo * sc)
                add(expr <= hi * sc)
            else:
                lit = z3.Or(expr < lo * sc, expr > hi * sc)
                viol.setdefault(dom, []).append(lit)

    bvars = []
    for d in domains:
        lits = viol.get(d)
        if lits:
            b = z3.Bool('b_' + d)
            add(b == z3.Or(lits))
            bvars.append(b)

    opt = z3.Optimize()
    opt.add(*base)
    sat = z3.Solver()
    sat.add(*base)

    # ---- minimum number of faulty domains -------------------------------
    if bvars:
        sat.push()
        sat.add(z3.PbLe([(b, 1) for b in bvars], max_faults))
        if sat.check() != z3.sat:
            sat.pop()
            return {'id': rid, 'status': 'infeasible'}
        sat.pop()
        lo, hi = 0, max_faults
        pb = [(b, 1) for b in bvars]
        while lo < hi:
            mid = (lo + hi) // 2
            sat.push()
            sat.add(z3.PbLe(pb, mid))
            ok = sat.check() == z3.sat
            sat.pop()
            if ok:
                hi = mid
            else:
                lo = mid + 1
        k = lo
    else:
        if sat.check() != z3.sat:
            return {'id': rid, 'status': 'infeasible'}
        k = 0

    # ---- restrict to the set F of optimal explanations -------------------
    pb_eq = z3.PbEq([(b, 1) for b in bvars], k) if bvars else None
    if pb_eq is not None:
        opt.push()
        opt.add(pb_eq)
        sat.push()
        sat.add(pb_eq)

    # ---- demand ranges ---------------------------------------------------
    demands = []
    unique = True
    for s in range(S):
        row = []
        for c in range(C):
            lo = opt_bound(opt, q[s][c], True)
            hi = opt_bound(opt, q[s][c], False)
            if lo != hi:
                unique = False
            row.append([lo, hi])
        demands.append(row)

    # ---- link ranges -----------------------------------------------------
    links = []
    for s in range(S):
        row = []
        for e in range(E):
            if all(a == 0 for a in A_col(e, A, C)):
                row.append(['0/1', '0/1'])
                continue
            nlo = opt_bound(opt, n[s][e], True)
            nhi = opt_bound(opt, n[s][e], False)
            row.append([_fmt(Fraction(nlo, L)), _fmt(Fraction(nhi, L))])
        links.append(row)

    # ---- controller verdicts --------------------------------------------
    verdicts = []
    for s, snap in enumerate(snaps):
        ctrl = snap[2]
        tol = snap[3]
        if C == 0:
            verdicts.append('consistent')
            continue
        agree = [z3.And(q[s][c] >= ctrl[c] - tol, q[s][c] <= ctrl[c] + tol)
                 for c in range(C)]
        good = z3.And(*agree)
        opt.push()
        opt.add(z3.Not(good))
        bad_exists = opt.check() == z3.sat
        opt.pop()
        opt.push()
        opt.add(good)
        good_exists = opt.check() == z3.sat
        opt.pop()
        if not bad_exists:
            verdicts.append('consistent')
        elif not good_exists:
            verdicts.append('inconsistent')
        else:
            verdicts.append('undetermined')

    # ---- forced / possible faulty domains --------------------------------
    forced = []
    possible = []
    if bvars:
        for d, b in zip(domains, bvars):
            opt.push()
            opt.add(b)
            if opt.check() == z3.sat:
                possible.append(d)
            opt.pop()
            opt.push()
            opt.add(z3.Not(b))
            if opt.check() != z3.sat:
                forced.append(d)
            opt.pop()

    # ---- witness ---------------------------------------------------------
    sat_res = sat.check()
    assert sat_res == z3.sat
    model = sat.model()
    wit_q = [[model[q[s][c]].as_long() for c in range(C)] for s in range(S)]
    wit_faults = _fault_set(inst, wit_q)

    alternative = None
    if not unique:
        diffs = []
        for s in range(S):
            for c in range(C):
                if demands[s][c][0] != demands[s][c][1]:
                    diffs.append(q[s][c] != wit_q[s][c])
        sat.push()
        sat.add(z3.Or(diffs))
        r2 = sat.check()
        assert r2 == z3.sat
        m2 = sat.model()
        alt_q = [[m2[q[s][c]].as_long() for c in range(C)] for s in range(S)]
        sat.pop()
        alternative = {
            'demands': alt_q,
            'links': _link_values(inst, alt_q, L),
            'faults': _fault_set(inst, alt_q),
        }

    if pb_eq is not None:
        opt.pop()
        sat.pop()

    snaps_out = []
    for s, snap in enumerate(snaps):
        snaps_out.append({
            'id': snap[0],
            'demands': demands[s],
            'links': links[s],
            'verdict': verdicts[s],
        })

    resp = {
        'id': rid,
        'status': 'unique' if unique else 'ambiguous',
        'min_faults': k,
        'faults': {'forced': forced, 'possible': possible},
        'snapshots': snaps_out,
        'witness': {
            'demands': wit_q,
            'links': _link_values(inst, wit_q, L),
            'faults': wit_faults,
        },
        'alternative': alternative,
    }
    return resp


def A_col(e, A, C):
    return (A[c][e] for c in range(C))


def opt_bound(opt, expr, minimize):
    opt.push()
    h = opt.minimize(expr) if minimize else opt.maximize(expr)
    res = opt.check()
    if res != z3.sat:
        opt.pop()
        raise AssertionError('bound query unsat')
    v = opt.lower(h) if minimize else opt.upper(h)
    val = int(str(v))
    opt.pop()
    return val


def _link_values(inst, wit_q, L):
    edges = inst['edges']
    coms = inst['commodities']
    E = len(edges)
    out = []
    for s, qrow in enumerate(wit_q):
        loads = [Fraction(0)] * E
        for ci, (_cid, _src, _tgt, routes) in enumerate(coms):
            wsum = sum(w for _p, w in routes)
            for path, w in routes:
                amt = Fraction(qrow[ci] * w, wsum)
                for ei in path:
                    loads[ei] += amt
        out.append([_fmt(v) for v in loads])
    return out


def _fault_set(inst, wit_q):
    edges = inst['edges']
    coms = inst['commodities']
    snaps = inst['snapshots']
    E = len(edges)
    faulty = set()
    for s, (sid, bnd, ctrl, tol, obs) in enumerate(snaps):
        qrow = wit_q[s]
        loads = [Fraction(0)] * E
        for ci, (_cid, _src, _tgt, routes) in enumerate(coms):
            wsum = sum(w for _p, w in routes)
            for path, w in routes:
                amt = Fraction(qrow[ci] * w, wsum)
                for ei in path:
                    loads[ei] += amt
        ing = {}
        egr = {}
        for ci, (_cid, src, tgt, _r) in enumerate(coms):
            ing[src] = ing.get(src, 0) + qrow[ci]
            egr[tgt] = egr.get(tgt, 0) + qrow[ci]
        metrics = {}
        for ci, cinfo in enumerate(coms):
            metrics[('demand', cinfo[0])] = qrow[ci]
        for ei, einfo in enumerate(edges):
            metrics[('link', einfo[0])] = loads[ei]
        for nn in inst['nodes']:
            metrics[('ingress', nn)] = ing.get(nn, 0)
            metrics[('egress', nn)] = egr.get(nn, 0)
        for (_oid, metric, target, lo, hi, dom) in obs:
            val = metrics[(metric, target)]
            if not (lo <= val <= hi):
                if dom is None:
                    raise AssertionError('trusted observation violated')
                faulty.add(dom)
    return sorted(faulty)


def main():
    data = sys.stdin.buffer.read()
    if not data:
        return
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    out = []
    for raw in lines:
        out.append(json.dumps(handle_line(raw), separators=(',', ':')))
    sys.stdout.write('\n'.join(out) + '\n')
    sys.stdout.flush()


if __name__ == '__main__':
    main()
